'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Lowercase Cyrillic -> Latin. Covers Russian plus the letters Ukrainian and
// Belarusian add; anything unmapped falls through to the non-alphanumeric rule.
const CYRILLIC = {
  а: 'a', б: 'b', в: 'v', г: 'g', ґ: 'g', д: 'd', е: 'e', ё: 'yo', є: 'ye',
  ж: 'zh', з: 'z', и: 'i', і: 'i', ї: 'yi', й: 'y', к: 'k', л: 'l', м: 'm',
  н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ў: 'u', ф: 'f',
  х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '',
  э: 'e', ю: 'yu', я: 'ya',
};

function transliterate(s) {
  let out = '';
  for (const ch of s) out += ch in CYRILLIC ? CYRILLIC[ch] : ch;
  return out;
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// options.wordBoundary: cut at the last word boundary that still fits instead of
// mid-word. If not even the first word fits there is no such boundary, so the
// result is the suffix alone. Default is the plain mid-word cut.
function truncate(input, maxLength, suffix = '…', options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const head = s.slice(0, Math.max(0, maxLength - suffix.length));
  if (!options.wordBoundary) return head + suffix;
  const cut = /\s/.test(s[head.length]) ? head : head.replace(/\S*$/, '');
  return cut.replace(/\s+$/, '') + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

function wordCount(input) {
  const s = String(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).length;
}

function titleCase(input) {
  return String(input)
    .split(/\s+/)
    .map((w) => (ACRONYMS.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = { slugify, truncate, capitalize, wordCount, titleCase, ACRONYMS };

'use strict';
// Tests for the BACKLOG.md items. tests/text.test.js is the pre-existing suite
// and must keep passing untouched; new behaviour is covered here.
const test = require('node:test');
const assert = require('node:assert');
const { slugify, truncate } = require('../src/text');

test('cyrillic-slug: slugify transliterates Cyrillic', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик щётка'), 'yozhik-shchyotka');
  // Letter-for-letter, so и->i and ї->yi (not the conventional spelling "Kyiv").
  assert.strictEqual(slugify('Київ'), 'kiyiv');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
  // Mixed scripts still produce one clean slug.
  assert.strictEqual(slugify('Тест v2 — beta!'), 'test-v2-beta');
});

test('truncate-word-boundary: default behaviour is unchanged', () => {
  assert.strictEqual(truncate('The quick brown fox', 12), 'The quick b…');
  assert.strictEqual(truncate('abcdefghij', 5), 'abcd…');
  assert.strictEqual(truncate('short', 20), 'short');
  // An absent or falsy flag is still the old behaviour.
  assert.strictEqual(truncate('The quick brown fox', 12, '…', {}), 'The quick b…');
  assert.strictEqual(
    truncate('The quick brown fox', 12, '…', { wordBoundary: false }),
    'The quick b…',
  );
});

test('truncate-word-boundary: cuts at the last word boundary that fits', () => {
  const opts = { wordBoundary: true };
  assert.strictEqual(truncate('The quick brown fox', 12, '…', opts), 'The quick…');
  // The result never exceeds maxLength.
  assert.ok(truncate('The quick brown fox', 12, '…', opts).length <= 12);
  // A word ending exactly at the budget is kept whole, not chopped back.
  assert.strictEqual(truncate('The quick brown fox', 10, '…', opts), 'The quick…');
  // Short enough to need no truncation at all.
  assert.strictEqual(truncate('short', 20, '…', opts), 'short');
  // A custom suffix is charged against the budget.
  assert.strictEqual(truncate('The quick brown fox', 12, '...', opts), 'The quick...');
  // No word boundary fits: only the suffix is left.
  assert.strictEqual(truncate('Supercalifragilistic', 8, '…', opts), '…');
});

