test('word-count-markdown: plain text is unchanged', () => {
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
  assert.strictEqual(wordCount(''), 0);
});

test('word-count-markdown: link text counts, the URL does not', () => {
  assert.strictEqual(wordCount('[click here](http://example.com/a/b)'), 2);
  assert.strictEqual(wordCount('see [the docs](http://example.com "Some Title")'), 3);
  assert.strictEqual(wordCount('![a picture](http://example.com/img.png)'), 2);
  assert.strictEqual(wordCount('a <http://example.com/very/long/path> link'), 2);
});

test('word-count-markdown: syntax markers do not count', () => {
  assert.strictEqual(wordCount('**bold** and *italic*'), 3);
  assert.strictEqual(wordCount('text ** bold ** here'), 3);
  assert.strictEqual(wordCount('# My Heading'), 2);
  assert.strictEqual(wordCount('### Deeper heading here'), 3);
  assert.strictEqual(wordCount('- one\n- two'), 2);
  assert.strictEqual(wordCount('* one\n+ two\n1. three'), 3);
  assert.strictEqual(wordCount('> quoted words'), 2);
  assert.strictEqual(wordCount('use `npm test` now'), 3);
  assert.strictEqual(wordCount('~~struck~~ out'), 2);
});

test('word-count-markdown: a realistic document', () => {
  const doc = [
    '# Release notes',
    '',
    'We shipped **two** things:',
    '',
    '- a [faster parser](https://example.com/parser)',
    '- better `errors`',
  ].join('\n');
  // Release notes | We shipped two things | a faster parser | better errors
  assert.strictEqual(wordCount(doc), 11);
});

