'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Lowercase Cyrillic -> Latin. Covers Russian plus the letters Ukrainian and
// Belarusian add; anything unmapped falls through to the non-alphanumeric rule.
const CYRILLIC = {
  а: 'a', б: 'b', в: 'v', г: 'g', ґ: 'g', д: 'd', е: 'e', ё: 'yo', є: 'ye',
  ж: 'zh', з: 'z', и: 'i', і: 'i', ї: 'yi', й: 'y', к: 'k', л: 'l', м: 'm',
  н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ў: 'u', ф: 'f',
  х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '',
  э: 'e', ю: 'yu', я: 'ya',
};

function transliterate(s) {
  let out = '';
  for (const ch of s) out += ch in CYRILLIC ? CYRILLIC[ch] : ch;
  return out;
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// options.wordBoundary: cut at the last word boundary that still fits instead of
// mid-word. If not even the first word fits there is no such boundary, so the
// result is the suffix alone. Default is the plain mid-word cut.
function truncate(input, maxLength, suffix = '…', options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const head = s.slice(0, Math.max(0, maxLength - suffix.length));
  if (!options.wordBoundary) return head + suffix;
  const cut = /\s/.test(s[head.length]) ? head : head.replace(/\S*$/, '');
  return cut.replace(/\s+$/, '') + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the text a reader actually sees: link and image text stays,
// the URL goes, and the syntax markers around them go.
function stripMarkdown(s) {
  return s
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/<[^>\s]+>/g, ' ')
    .replace(/^[ \t]*(?:(?:#{1,6}|>|[-*+]|\d+[.)])[ \t]+)+/gm, '')
    .replace(/[*_~`]/g, '');
}

function wordCount(input) {
  const s = stripMarkdown(String(input)).trim();
  if (!s) return 0;
  // Leftover punctuation is not a word; a token needs a letter or a digit.
  return s.split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
}

const WORDS_PER_MINUTE = 200;

// Whole minutes, rounded up, so anything with at least one word reads as 1+.
// Text with nothing to read (empty or whitespace/markup only) is 0.
function readingTime(input) {
  const words = wordCount(input);
  return words === 0 ? 0 : Math.ceil(words / WORDS_PER_MINUTE);
}

function titleCase(input) {
  return String(input)
    .split(/\s+/)
    .map((w) => (ACRONYMS.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = { slugify, truncate, capitalize, wordCount, readingTime, titleCase, ACRONYMS };

