// matched against the uppercased word, so list them uppercase. A Set is the
// natural argument; any iterable of strings also works.
function titleCase(input, acronyms = ACRONYMS) {
  const known = acronyms instanceof Set ? acronyms : new Set(acronyms);
  return String(input)
    .split(/\s+/)
    .map((w) => (known.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = {
  slugify,
  truncate,
  capitalize,
  wordCount,
  readingTime,
  escapeHtml,
  titleCase,
  ACRONYMS,
};

