} = require('../src/text');

test('cyrillic-slug: slugify transliterates Cyrillic', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик щётка'), 'yozhik-shchyotka');
  // Letter-for-letter, so и->i and ї->yi (not the conventional spelling "Kyiv").
  assert.strictEqual(slugify('Київ'), 'kiyiv');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
  // Mixed scripts still produce one clean slug.
  assert.strictEqual(slugify('Тест v2 — beta!'), 'test-v2-beta');
});

test('truncate-word-boundary: default behaviour is unchanged', () => {
  assert.strictEqual(truncate('The quick brown fox', 12), 'The quick b…');
  assert.strictEqual(truncate('abcdefghij', 5), 'abcd…');
  assert.strictEqual(truncate('short', 20), 'short');
  // An absent or falsy flag is still the old behaviour.
  assert.strictEqual(truncate('The quick brown fox', 12, '…', {}), 'The quick b…');
  assert.strictEqual(
    truncate('The quick brown fox', 12, '…', { wordBoundary: false }),
    'The quick b…',
  );
});

test('truncate-word-boundary: cuts at the last word boundary that fits', () => {
  const opts = { wordBoundary: true };
  assert.strictEqual(truncate('The quick brown fox', 12, '…', opts), 'The quick…');
  // The result never exceeds maxLength.
  assert.ok(truncate('The quick brown fox', 12, '…', opts).length <= 12);
  // A word ending exactly at the budget is kept whole, not chopped back.
  assert.strictEqual(truncate('The quick brown fox', 10, '…', opts), 'The quick…');
  // Short enough to need no truncation at all.
  assert.strictEqual(truncate('short', 20, '…', opts), 'short');
  // A custom suffix is charged against the budget.
  assert.strictEqual(truncate('The quick brown fox', 12, '...', opts), 'The quick...');
  // No word boundary fits: only the suffix is left.
  assert.strictEqual(truncate('Supercalifragilistic', 8, '…', opts), '…');
});

test('word-count-markdown: plain text is unchanged', () => {
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
  assert.strictEqual(wordCount(''), 0);
});

test('word-count-markdown: link text counts, the URL does not', () => {
  assert.strictEqual(wordCount('[click here](http://example.com/a/b)'), 2);
  assert.strictEqual(wordCount('see [the docs](http://example.com "Some Title")'), 3);
  assert.strictEqual(wordCount('![a picture](http://example.com/img.png)'), 2);
  assert.strictEqual(wordCount('a <http://example.com/very/long/path> link'), 2);
});

test('word-count-markdown: syntax markers do not count', () => {
  assert.strictEqual(wordCount('**bold** and *italic*'), 3);
  assert.strictEqual(wordCount('text ** bold ** here'), 3);
  assert.strictEqual(wordCount('# My Heading'), 2);
  assert.strictEqual(wordCount('### Deeper heading here'), 3);
  assert.strictEqual(wordCount('- one\n- two'), 2);
  assert.strictEqual(wordCount('* one\n+ two\n1. three'), 3);
  assert.strictEqual(wordCount('> quoted words'), 2);
  // Backticks go, the code inside them is still text the reader reads.
  assert.strictEqual(wordCount('use `npm test` now'), 4);
  assert.strictEqual(wordCount('~~struck~~ out'), 2);
});

test('word-count-markdown: a realistic document', () => {
  const doc = [
    '# Release notes',
    '',
    'We shipped **two** things:',
    '',
    '- a [faster parser](https://example.com/parser)',
    '- better `errors`',
  ].join('\n');
  // Release notes | We shipped two things | a faster parser | better errors
  assert.strictEqual(wordCount(doc), 11);
});

test('reading-time: whole minutes at 200 words per minute', () => {
  const words = (n) => Array.from({ length: n }, (_, i) => `w${i}`).join(' ');
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('one'), 1);
  assert.strictEqual(readingTime(words(199)), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(201)), 2);
  assert.strictEqual(readingTime(words(400)), 2);
  assert.strictEqual(readingTime(words(401)), 3);
  assert.strictEqual(readingTime(words(1000)), 5);
});

test('reading-time: nothing to read is zero minutes', () => {
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  // Markup with no visible words is nothing to read either.
  assert.strictEqual(readingTime('## '), 0);
});

test('escape-html: escapes the five characters', () => {
  assert.strictEqual(escapeHtml('&'), '&amp;');
  assert.strictEqual(escapeHtml('<'), '&lt;');
  assert.strictEqual(escapeHtml('>'), '&gt;');
  assert.strictEqual(escapeHtml('"'), '&quot;');
  assert.strictEqual(escapeHtml("'"), '&#39;');
  assert.strictEqual(escapeHtml(''), '');
  assert.strictEqual(escapeHtml('nothing to escape'), 'nothing to escape');
});

test('escape-html: the ampersand is never double-escaped', () => {
  // The & of each emitted entity must survive as a literal &, not become &amp;.
  assert.strictEqual(escapeHtml('a < b'), 'a &lt; b');
  assert.strictEqual(escapeHtml('Tom & Jerry'), 'Tom &amp; Jerry');
